// An alert: while presented, a card is laid over a dimmed presenter, which takes no taps. Any of
// its buttons ends the presentation; an alert without actions gets OK.
private struct AlertDismissKey: EnvironmentKey { static let defaultValue: (() -> Void)? = nil }
extension EnvironmentValues {
    var _alertDismiss: (() -> Void)? {
        get { self[AlertDismissKey.self] }
        set { self[AlertDismissKey.self] = newValue }
    }
}
struct _AlertLayer<Base: View, Actions: View, Message: View>: View {
    let base: Base
    let title: Text
    let isPresented: Binding<Bool>
    let shown: Bool
    let actions: Actions?
    let message: Message?
    var body: some View {
        ZStack {
            base
            if shown && isPresented.wrappedValue {
                Button(action: {}) {
                    Color.black.opacity(0.35).frame(maxWidth: .infinity, maxHeight: .infinity)
                }
                VStack(spacing: 14) {
                    title
                    if let message { message }
                    VStack(spacing: 10) {
                        if let actions, Actions.self != EmptyView.self { actions } else { Button("OK", action: {}) }
                    }
                }
                .padding(20)
                .frame(width: 270)
                .background(Color(uiColor: .systemBackground))
                .environment(\._alertDismiss, { isPresented.wrappedValue = false })
            }
        }
    }
}
@available(iOS, introduced: 13.0, deprecated: 100000.0, message: "use `View.alert(title:isPresented:presenting::actions:) instead.")
@available(macOS, introduced: 10.15, deprecated: 100000.0, message: "use `View.alert(title:isPresented:presenting::actions:) instead.")
@available(tvOS, introduced: 13.0, deprecated: 100000.0, message: "use `View.alert(title:isPresented:presenting::actions:) instead.")
@available(watchOS, introduced: 6.0, deprecated: 100000.0, message: "use `View.alert(title:isPresented:presenting::actions:) instead.")
public struct Alert {
  fileprivate let title: Text
  fileprivate let message: Text?
  fileprivate let buttons: [Button]
  public init(title: Text, message: Text? = nil, dismissButton: Alert.Button? = nil) {
    self.title = title
    self.message = message
    buttons = dismissButton.map { [$0] } ?? []
  }
  public init(title: Text, message: Text? = nil, primaryButton: Alert.Button, secondaryButton: Alert.Button) {
    self.title = title
    self.message = message
    // Whichever button cancels goes first, as UIAlertController places it.
    buttons = primaryButton.role != .cancel && secondaryButton.role == .cancel ? [secondaryButton, primaryButton] : [primaryButton, secondaryButton]
  }
  @available(iOS, unavailable)
  @available(tvOS, unavailable)
  @available(macOS, unavailable)
  public static func sideBySideButtons(title: Text, message: Text? = nil, primaryButton: Alert.Button, secondaryButton: Alert.Button) -> Alert {
    Alert(title: title, message: message, primaryButton: primaryButton, secondaryButton: secondaryButton)
  }
  public struct Button {
    fileprivate let label: Text
    fileprivate let action: (() -> Swift.Void)?
    fileprivate let role: ButtonRole?
    public static func `default`(_ label: Text, action: (() -> Swift.Void)? = {}) -> Alert.Button {
      Alert.Button(label: label, action: action, role: nil)
    }
    public static func cancel(_ label: Text, action: (() -> Swift.Void)? = {}) -> Alert.Button {
      Alert.Button(label: label, action: action, role: .cancel)
    }
    public static func cancel(_ action: (() -> Swift.Void)? = {}) -> Alert.Button {
      .cancel(Text(verbatim: "Cancel"), action: action)
    }
    public static func destructive(_ label: Text, action: (() -> Swift.Void)? = {}) -> Alert.Button {
      Alert.Button(label: label, action: action, role: .destructive)
    }
  }
}
private struct _AlertButton: View {
  let button: Alert.Button
  var body: some View {
    Button(role: button.role, action: { button.action?() }) { button.label }
  }
}
struct _AlertButtons: View {
  fileprivate let buttons: [Alert.Button]
  var body: some View {
    if buttons.count == 2 {
      HStack(spacing: 20) {
        _AlertButton(button: buttons[0])
        _AlertButton(button: buttons[1])
      }
    } else if let button = buttons.first {
      _AlertButton(button: button)
    }
  }
}
extension View {
    // alert is nil while nothing is presented: an app's content closure may rely on the state
    // that presents it, so it runs only then.
    func _alertLayer(isPresented: Binding<Bool>, alert: Alert?) -> some View {
        _AlertLayer(base: self, title: alert?.title ?? Text(verbatim: ""), isPresented: isPresented, shown: alert != nil,
                    actions: alert.flatMap { $0.buttons.isEmpty ? nil : _AlertButtons(buttons: $0.buttons) }, message: alert?.message)
    }
}
extension View {
    public func alert<A: View, M: View>(_ titleKey: LocalizedStringKey, isPresented: Binding<Bool>,
                                      @ViewBuilder actions: () -> A, @ViewBuilder message: () -> M) -> some View {
        _AlertLayer(base: self, title: Text(titleKey), isPresented: isPresented, shown: true, actions: actions(), message: message())
    }
    public func onOpenURL(perform action: @escaping (URL) -> Void) -> some View {
        OpenURLView(content: self, action: action)
    }
    public func alert<A: View, M: View, T>(_ titleKey: LocalizedStringKey, isPresented: Binding<Bool>,
        presenting data: T?, @ViewBuilder actions: (T) -> A, @ViewBuilder message: (T) -> M) -> some View {
        _AlertLayer(base: self, title: Text(titleKey), isPresented: isPresented, shown: data != nil,
                    actions: data.map(actions), message: data.map(message))
    }
    @_disfavoredOverload public func alert<S: StringProtocol, A: View, M: View, T>(_ title: S, isPresented: Binding<Bool>,
        presenting data: T?, @ViewBuilder actions: (T) -> A, @ViewBuilder message: (T) -> M) -> some View {
        _AlertLayer(base: self, title: Text(verbatim: String(title)), isPresented: isPresented, shown: data != nil,
                    actions: data.map(actions), message: data.map(message))
    }
    public func alert<A: View, M: View, T>(_ title: Text, isPresented: Binding<Bool>,
        presenting data: T?, @ViewBuilder actions: (T) -> A, @ViewBuilder message: (T) -> M) -> some View {
        _AlertLayer(base: self, title: title, isPresented: isPresented, shown: data != nil,
                    actions: data.map(actions), message: data.map(message))
    }
}

private var openURLHandlers: [(URL) -> Void] = []
func clearOpenURLHandlers() { openURLHandlers.removeAll() }
private struct OpenURLView<Content: View>: View {
    let content: Content
    let action: (URL) -> Void
    typealias Body = Never
    static func _makeView(view: _GraphValue<Self>, inputs: _ViewInputs) -> _ViewOutputs {
        let objects = inputs.objects
        let action = view.value.action
        openURLHandlers.append { url in EnvironmentScope.withObjects(objects) { action(url) } }
        return Content._makeView(view: _GraphValue(value: view.value.content), inputs: inputs)
    }
}
// Backend event entry point. This is also used by the independent SDK fixture
// to verify that evaluating the view does not invoke the action prematurely.
@_cdecl("iosandroid_swiftui_open_url")
public func _dispatchOpenURL(_ string: UnsafePointer<CChar>) -> Bool {
    guard let url = URL(string: String(cString: string)) else { return false }
    let snapshot = openURLHandlers
    for action in snapshot { action(url) }
    return !snapshot.isEmpty
}
// An action read outside a presented destination has nothing to dismiss.
public struct DismissAction {
    let action: (() -> Void)?
    fileprivate init(action: (() -> Void)? = nil) { self.action = action }
    public func callAsFunction() { action?() }
}
private struct DismissKey: EnvironmentKey { static let defaultValue = DismissAction() }
extension EnvironmentValues {
    public var dismiss: DismissAction { self[DismissKey.self] }
    public var isPresented: Bool { self[DismissKey.self].action != nil }
    var _presentationDismiss: DismissAction {
        get { self[DismissKey.self] }
        set { self[DismissKey.self] = newValue }
    }
}

// Sheets and full-screen covers: while presented, the content is laid over the presenter, filling
// it, on the system background; dismiss and presentationMode inside it end the presentation.
struct _PresentedLayer<Base: View, Presented: View>: View {
    let base: Base
    let isPresented: Binding<Bool>
    let onDismiss: (() -> Void)?
    let presented: () -> Presented
    var body: some View {
        ZStack {
            base
            if isPresented.wrappedValue {
                presented()
                    .frame(maxWidth: .infinity, maxHeight: .infinity)
                    .background(Color(uiColor: .systemBackground))
                    .environment(\._presentationDismiss, DismissAction(action: {
                        isPresented.wrappedValue = false
                        onDismiss?()
                    }))
            }
        }
    }
}

func _itemPresented<Item>(_ item: Binding<Item?>) -> Binding<Bool> {
    Binding(get: { item.wrappedValue != nil }, set: { if !$0 { item.wrappedValue = nil } })
}

extension View {
    public func sheet<Item, Content>(item: Binding<Item?>, onDismiss: (() -> Void)? = nil, @ViewBuilder content: @escaping (Item) -> Content) -> some View where Item: Identifiable, Content: View {
        _PresentedLayer(base: self, isPresented: _itemPresented(item), onDismiss: onDismiss) { content(item.wrappedValue!) }
    }
    public func sheet<Content>(isPresented: Binding<Bool>, onDismiss: (() -> Void)? = nil, @ViewBuilder content: @escaping () -> Content) -> some View where Content: View {
        _PresentedLayer(base: self, isPresented: isPresented, onDismiss: onDismiss, presented: content)
    }
    public func fullScreenCover<Item, Content>(item: Binding<Item?>, onDismiss: (() -> Void)? = nil, @ViewBuilder content: @escaping (Item) -> Content) -> some View where Item: Identifiable, Content: View {
        _PresentedLayer(base: self, isPresented: _itemPresented(item), onDismiss: onDismiss) { content(item.wrappedValue!) }
    }
    public func fullScreenCover<Content>(isPresented: Binding<Bool>, onDismiss: (() -> Void)? = nil, @ViewBuilder content: @escaping () -> Content) -> some View where Content: View {
        _PresentedLayer(base: self, isPresented: isPresented, onDismiss: onDismiss, presented: content)
    }
}

